      "ids": ["EFF-05"],
      "type": "logical",
      "description": "Allowing temporary overdrafts could lead to unauthorized transactions, conflicting with TRU-04, which ensures financial integrity."
    },
    {
      "ids": ["SAF-01", "SAF-03"],
      "type": "logical",
      "description": "Temporary overdrafts could create unsafe scenarios that undermine user trust and safety."
    }
